CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),business_name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,trial_ends_at TIMESTAMPTZ NOT NULL,industry TEXT,business_size TEXT,role TEXT NOT NULL DEFAULT 'business',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,target_url TEXT NOT NULL,score INT NOT NULL,findings JSONB NOT NULL,authorized BOOLEAN NOT NULL,engine TEXT,priority TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,external_id TEXT UNIQUE NOT NULL,trans_id TEXT,amount INT NOT NULL,service TEXT NOT NULL,status TEXT NOT NULL,link TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE TABLE IF NOT EXISTS news(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title TEXT NOT NULL,excerpt TEXT NOT NULL,body TEXT NOT NULL,category TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),published BOOLEAN NOT NULL DEFAULT TRUE);
